-- Phase 8 catalogue search (system-design.md §8, D-110): PostgreSQL full-text
-- search plus pg_trgm for typo tolerance and prefix suggestions.
--
-- Sections:
--   1. Column and GIN index (generated by prisma migrate diff)
--   2. Trigram extension, trigram index and the search-document function (handwritten)
-- Handwritten objects are listed in apps/api/src/db/handwritten.ts.

-- ═══ 1. Generated by prisma migrate diff (Prisma 7.10.1) ════════════════════
-- AlterTable
ALTER TABLE "product" ADD COLUMN     "search_vector" tsvector;

-- CreateIndex
CREATE INDEX "product_search_vector_idx" ON "product" USING GIN ("search_vector");

-- ═══ 2. Handwritten ══════════════════════════════════════════════════════════
CREATE EXTENSION IF NOT EXISTS "pg_trgm";

-- Typo-tolerant name matching and suggestions (`similarity`, `%`).
CREATE INDEX "product_name_trgm_idx" ON "product" USING GIN (lower("name") gin_trgm_ops);

-- Rebuilds one product's search document from its name (weight A), category
-- and collection names (B), colour names and short description (C) and the
-- text of its structured description blocks (D). The API calls it after every
-- change that affects these values; it never reads client input directly.
CREATE FUNCTION "refresh_product_search"(target uuid) RETURNS void
LANGUAGE sql AS $$
  UPDATE "product" p SET "search_vector" =
    setweight(to_tsvector('english', coalesce(p."name", '')), 'A') ||
    setweight(to_tsvector('english', coalesce((
      SELECT c."name" FROM "category" c WHERE c."id" = p."category_id"), '')), 'B') ||
    setweight(to_tsvector('english', coalesce((
      SELECT string_agg(col."name", ' ') FROM "collection_product" cp
      JOIN "collection" col ON col."id" = cp."collection_id"
      WHERE cp."product_id" = p."id"), '')), 'B') ||
    setweight(to_tsvector('english', coalesce((
      SELECT string_agg(DISTINCT co."name", ' ') FROM "product_variant" v
      JOIN "colour" co ON co."id" = v."colour_id"
      WHERE v."product_id" = p."id"), '')), 'C') ||
    setweight(to_tsvector('english', coalesce(p."short_description", '')), 'C') ||
    setweight(to_tsvector('english', coalesce((
      SELECT string_agg(t, ' ') FROM jsonb_path_query(p."description", 'strict $.**.text') AS j(v),
      LATERAL (SELECT v #>> '{}' AS t) x WHERE jsonb_typeof(v) = 'string'), '')), 'D')
  WHERE p."id" = target;
$$;
